type retiredRoute struct {
	route   string // "METHOD /v1/workspaces/{ws}/..."
	instead string
}

// retiredOps names each retired route's operation by its pattern, for the
// request log and install health (the operations are no longer in
// api/openapi.yaml).
var retiredOps = func() map[string]string {
	m := make(map[string]string, len(retiredRoutes))
	for op, rt := range retiredRoutes {
		m[rt.route] = op
	}
	return m
}()

// routeMoved answers a call to a retired route, once the caller's access
// to the workspace is known (so the call is in that workspace's log and
// install health), with 410 route_moved and the route to call instead.
// It reports whether it answered.
func routeMoved(w http.ResponseWriter, r *http.Request) bool {
	op, ok := retiredOps[r.Pattern]
	if !ok {
		return false
	}
	writeError(w, r, http.StatusGone, "route_moved", "This route moved: call "+retiredRoutes[op].instead+" instead. Brands are fully separate, so brand data is under /v1/brands/{brand}/ (find the brand's id with GET /v1/workspaces/{ws}/brands).")
	return true
}

// retiredGate is where this package's tests send a call to a retired
// workspace route on to its brand route (testRetiredServe), so tests
// written against the workspace routes keep testing the same handlers.
// Elsewhere it passes every call through.
func (s *Server) retiredGate(mux *http.ServeMux) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if testRetiredServe != nil {
			if _, pattern := mux.Handler(r); pattern != "" {
				if op, ok := retiredOps[pattern]; ok && testRetiredServe(s, mux, w, r, retiredRoutes[op]) {
					return
				}
			}
		}
		mux.ServeHTTP(w, r)
	})
}

// testRetiredServe, set only by this package's tests, serves a call to a
// retired route on its brand route, and reports whether it did.
var testRetiredServe func(s *Server, mux http.Handler, w http.ResponseWriter, r *http.Request, rt retiredRoute) bool
